def link_orders_to_their_quoted_line(apps, schema_editor):
    """Orders placed from a quotation before this existed: link each to the line (newest quotation of its query first)
    with the same grade, width and thickness, so it shows the price it was quoted. Orders with no match stay unpriced."""
    Order = apps.get_model('materials', 'Order')
    Quotation = apps.get_model('materials', 'Quotation')
    for order in Order.objects.exclude(source_query=None).filter(quotation_line=None):
        for quotation in Quotation.objects.filter(source_query_id=order.source_query_id, status='sent').order_by('-quotation_no'):
            line = next((l for l in quotation.line_items.all()
                         if (l.grade or '').lower() == (order.grade or '').lower()
                         and l.width == order.width and l.thickness == order.thickness), None)
            if line:
                order.quotation_line = line
                order.save(update_fields=['quotation_line'])
                break


